        rows.sort(key=lambda row: _split_subdomain(row[0]))
    elif sort == "endpoint":
        rows.sort(key=lambda row: row[1])
    elif sort == "rule":
        rows.sort(key=lambda row: row[3])
    elif sort == "methods":
        rows.sort(key=lambda row: sorted(row[2].split(", ")))

    if not has_domain:
        headers.pop(0)
        rows = [[row[1], row[2], row[3]] for row in rows]

    widths = [
        max(len(header), *(len(str(row[i])) for row in rows))
        for i, header in enumerate(headers)
    ]
    line = "  ".join(header.ljust(width) for header, width in zip(headers, widths))
    click.echo(line.rstrip())
    click.echo("  ".join("-" * width for width in widths).rstrip())

    for row in rows:
        line = "  ".join(str(val).ljust(width) for val, width in zip(row, widths))
        click.echo(line.rstrip())


